syntax:
storage-class-specifier declaration;
// Examples:
extern int global_var;
static int internal_var;
register int fast_access_var;
auto int local_var; // default for local variables

code_example:
/* File: module.c */
static int internal_counter = 0; // internal linkage, persists across function calls within this file
extern int shared_counter; // declares a variable defined elsewhere
void increment_counters() {
    internal_counter++; // modifies static variable with internal linkage
    shared_counter++;   // modifies external variable
}
/* File: main.c */
int shared_counter = 0; // definition of external variable
int main() {
    increment_counters();
    printf("Internal: %d, Shared: %d\n", internal_counter, shared_counter);
    return 0;
}
